//! The shapes of the Public Suffix List tables in [`super::data`]
//! (generated by `cargo xtask tables`).

#[allow(unused_imports)]
use vstd::prelude::*;

verus! {

/// A rule of the list: its labels, from left to right, are rows `first ..
/// first + count` of `PSL_LABELS`, and `exception` is whether the line
/// started with `!`.
#[derive(Clone, Copy)]
pub struct RuleRow {
    /// The row of `PSL_LABELS` that holds the rule's leftmost label.
    pub first: u32,
    /// The number of labels.
    pub count: u32,
    /// Whether this is an exception rule.
    pub exception: bool,
}

/// A label: the characters `PSL_CHARS[start .. start + len]`.
#[derive(Clone, Copy)]
pub struct LabelRow {
    /// Where the label starts in `PSL_CHARS`.
    pub start: u32,
    /// The label's length.
    pub len: u32,
}

} // verus!
